template-columns:1fr 1fr 1fr;gap:24px;padding:16px 24px}label{display:flex;flex-direction:column;gap:4px;min-width:0;font-size:12px;color:var(--muted)}select{font-size:14px;width:100%;min-height:44px;padding:8px 12px;color:var(--fg);border:1px solid var(--bd);border-radius:6px;background:var(--card);cursor:pointer}select:disabled{opacity:.55}.wrap{position:relative;background:#527d79;isolation:isolate}canvas{width:100%;display:block;aspect-ratio:800/420;touch-action:none}.scene-caption{position:absolute;bottom:16px;right:20px;left:20px;display:flex;justify-content:space-between;align-items:center;pointer-events:none;color:#fff;text-shadow:0 1px 4px #15382f;font-size:12px}.scene-caption>span:first-child{font-size:16px;font-weight:600}#scene-detail{background:#203f35ed;border-radius:4px;padding:4px 12px;text-shadow:none}.controls{display:flex;gap:24px;align-items:center;justify-content:space-between;padding:24px}.feedback{min-width:0}#msg{font-size:16px;font-weight:600}.feedback p{font-size:12px;color:var(--muted);margin-top:8px}.cast-action{min-width:265px;text-align:center}#btn{width:100%;min-height:48px;font-size:16px;user-select:none;-webkit-user-select:none;touch-action:none}.cast-action>span{display:block;font-size:12px;color:var(--muted);margin-top:8px}kbd{font:inherit;border:1px solid var(--bd);border-radius:4px;padding:1px 6px}.journal{padding:32px 0 40px}.journal-heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:20px}#stat{color:var(--muted);font-size:12px}.table-scroll{overflow-x:auto}#hist{width:100%;border-collapse:collapse;text-align:left;font-size:14px}#hist th{font-size:12px;font-weight:400;color:var(--muted);padding:8px 12px;border-bottom:1px solid var(--bd)}#hist td{padding:12px;border-bottom:1px solid var(--bd);white-space:nowrap}#hist .empty{text-align:center;white-space:normal;padding:28px;color:var(--muted);background:var(--soft);border:0}footer{display:flex;justify-content:space-between;border-top:1px solid var(--b