@media(max-width:700px){body{padding:0 16px}.top{gap:16px;flex-wrap:wrap;padding:20px 0 12px}.brand{font-size:20px}.top nav{order:3;width:100%;margin:0;gap:0;justify-content:space-between}.top nav button{padding:8px 12px}.money{margin-left:auto;min-width:72px;padding-left:16px}.heading{padding:24px 0 16px}.intro{display:none}h1{font-size:24px}.row{padding:16px;gap:12px;grid-template-columns:1fr 1fr}.row label:first-child{grid-column:1/-1}.wrap{overflow:hidden}canvas{width:100%;max-width:100%}.scene-caption{left:12px;right:12px;bottom:12px}.scene-caption>span:first-child{font-size:14px}#scene-detail{font-size:12px;padding:4px 8px}.controls{padding:16px;flex-direction:column;gap:16px;align-items:stretch}.cast-action{min-width:0}.feedback p{margin-top:4px}.journal{padding:24px 0 32px}.journal-heading{gap:16px;align-items:center}h2{font-size:20px}.journal-heading .kicker{display:none}#stat{max-width:110px;text-align:right}footer{gap:16px}.mb{padding:20px;max-height:90vh}.modal{padding:12px}.mb td{font-size:12px}.mb td:last-child{min-width:104px}.mb button{padding:8px}.mb td:first-child{min-width:82px}.mb .fl{font-size:12px}#tut{flex-direction:column;align-items:start}#card>div{padding:20px;min-width:260px}#card .big{font-size:24px}}
.scene-caption{position:relative;inset:auto;background:#203f35;min-height:44px;padding:8px 20px;text-shadow:none;gap:12px}.scene-caption #scene-detail{background:transparent;padding:0;font-size:12px}.scene-caption>span:first-child{font-size:14px}@media(max-width:700px){.scene-caption{padding:8px 12px;gap:8px}.scene-caption #scene-detail{font-size:10px}}
.location-control{display:flex;flex-direction:column;gap:4px;min-width:0}.location-control>span{font-size:12px;color:var(--muted)}.location-control b{font-weight:400}.location-control button{display:flex;justify-content:space-between;align-items:center;text-align:left;padding:8px 12px}.location-modal{background:rgba(8,15,19,.82);padding:32px}.location-window{background:#252f3b;color:#f7f8fa;border:1px solid #536171;border-radius:16px;width:1240px;max-width:100%;max-height:92vh;overflow:auto;box-shadow:0 24px 80px #0008;padding:24px}.location-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin-bottom:24px}.location-heading>div{flex:1;text-align:center;padding-left:68px}.location-heading h2{font-size:28px;letter-spacing:-.02em;line-height:1.2;margin:4px 0 8px}.location-heading p{color:#c8d1db}.location-close{background:#5e536e;font-size:32px;line-height:1;padding:0;width:44px;flex-shrink:0}.location-close:hover{background:#756786}.location-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.location-option{background:#424f60;padding:16px;border-radius:12px;display:flex;flex-direction:column;min-width:0;border:2px solid transparent}.location-option.is-current{border-color:#bdcfae}.location-preview{width:100%;aspect-ratio:1.85;object-fit:cover;border-radius:10px;display:block}.location-option h3{font-size:20px;line-height:1.2;text-align:center;margin:12px 0 4px;font-weight:600}.location-habitat{font-size:12px;color:#e0e6ed;text-align:center;margin-bottom:16px}.fish-panel{background:#252f3b;border:1px solid #7f90a5;border-radius:10px;padding:12px 8px;margin-bottom:8px}.fish-panel h4{font-size:16px;line-height:1.3;text-align:center;margin:0 0 8px;font-weight:600}.popular-fish,.weight-fish{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;align-items:start}.weight-fish{grid-template-columns:repeat(2,minmax(0,1fr))}.location-fish{text-align:center;min-width:0;font-size:12px;font-weight:600;line-hei